mapper.update:
UPDATE SF_INCIDENT
SET STATUS = #{status}, UPDATED_AT = SYSTIMESTAMP
WHERE INCIDENT_ID = #{incidentId}

UPDATE SF_INCIDENT
SET ASSIGNED_STAFF_ID = #{staffId}, UPDATED_AT = SYSTIMESTAMP
WHERE INCIDENT_ID = #{incidentId}

UPDATE SF_INCIDENT
SET STATUS = 'CLOSED', CLOSE_REASON = #{closeReason}, UPDATED_AT = SYSTIMESTAMP
WHERE INCIDENT_ID = #{incidentId}

mapper.select:
SELECT * FROM SF_INCIDENT_LOG
WHERE INCIDENT_ID = #{incidentId}
ORDER BY CHANGED_AT ASC

SELECT COUNT(*) FROM SF_INCIDENT_LOG
WHERE NEW_STATUS = 'CLOSED'
  AND TRUNC(CHANGED_AT) = #{date}

SELECT PHOTO_URL FROM SF_INCIDENT_PHOTO
WHERE INCIDENT_ID = #{incidentId}
ORDER BY SORT_ORDER
